const NOW = Date.now();
const cfg = (($('Config ophalen').all()[0]||{}).json)||{};
const DEFAULT_TH = (cfg.thresholds && cfg.thresholds.default) || {};
const MACHINES = $('Machines ophalen').all().map(x=>x.json);
const TH = DEFAULT_TH;
const OFFLINE_MIN = TH.offline_min ?? 10, UPD_MANY = TH.updates_many ?? 20;
const BAT_MIN = TH.bat_min ?? 15, DISK_WARN = TH.disk_warn ?? 80, DISK_ALARM = TH.disk_alarm ?? 90;
const TEMP_ALARM = TH.temp_alarm ?? 90;
const num = v => (v==null||v==='')?NaN:Number(v);
const tms = r => Date.parse(r.ts);
const hhmm = () => new Date(NOW).toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Amsterdam'});
const asArr = v => Array.isArray(v)?v:(typeof v==='string'?(()=>{try{return JSON.parse(v)}catch(e){return null}})():null);
const latest = $input.all().map(i=>i.json);
const rows=MACHINES.map(m=>({...latest.find(r=>r.machine===m.machine),machine:m.machine,thresholds:m.thresholds}));          // v_latest: 1 rij per machine
const online = rows.filter(r=>!isNaN(tms(r)) && (NOW-tms(r))/60000 <= ({...DEFAULT_TH,...(r.thresholds||{})}.offline_min??10));
const label = m => (m||'?');

const t=hhmm(); const store=$getWorkflowStaticData('global'); store.u=store.u||{}; store.f=store.f||{};
const out=[];
function fire(m,key,active,spec,caption){
  const id=m+':'+key; const was=!!store.f[id];
  if(active && !was){ store.f[id]=true; out.push({json:{caption,spec}}); }
  else if(!active && was){ store.f[id]=false;
    out.push({json:{caption:'✓ Opgelost — '+m+' · '+t,
      spec:{title:'✓ Opgelost — '+m,subtitle:t,state:'ok',
        rows:[{label:key.toUpperCase(),value:'weer OK',status:'ok'}],footer:'SysDash · updates · '+t}}}); }
}
for(const d of online){
  const T={...DEFAULT_TH,...(d.thresholds||{})};
  const OFFLINE_MIN=T.offline_min??10,UPD_MANY=T.updates_many??20,BAT_MIN=T.bat_min??15,DISK_WARN=T.disk_warn??80,DISK_ALARM=T.disk_alarm??90,TEMP_ALARM=T.temp_alarm??90,DISK_FORECAST_DAYS=T.disk_forecast_days??14,RAM_ALARM=T.ram_alarm??85,SWAP_ALARM=T.swap_alarm??50;
  const m=label(d.machine); const upd=num(d.updates); if(isNaN(upd)) continue;
  const ex = d.extra || {};
  const cat = upd<=0?'uptodate':(upd>UPD_MANY?'many':'some');
  const prev = store.u[m];
  if(prev===undefined){ store.u[m]=cat; }
  else if(cat!==prev){ store.u[m]=cat;
    if(cat==='uptodate'){
      out.push({json:{caption:'✓ Up-to-date — '+m,
        spec:{title:'✓ Alles bijgewerkt — '+m,subtitle:t,state:'ok',
          rows:[{label:'UPDATES',value:'up-to-date',status:'ok'}],footer:'SysDash · updates · '+t}}});
    } else {
      const sym = cat==='many'?'⚠':'●'; const st = cat==='many'?'high':'warn';
      out.push({json:{caption:sym+' Updates — '+m+' · '+upd+' klaar',
        spec:{title:sym+' Updates beschikbaar — '+m,subtitle:t,state: cat==='many'?'alert':'ok',
          rows:[{label:'UPDATES',value:upd+' klaar',status:st}],footer:'SysDash · updates · '+t}}});
    }
  }

  // herstart nodig (na een update) — eenmalig seintje, lost zichzelf op na de herstart
  const reboot = !!ex.reboot_required;
  fire(m,'herstart',reboot,{title:'● Herstart nodig — '+m,subtitle:t,state:'ok',
    rows:[{label:'HERSTART',value:'nodig na update',status:'warn'}],footer:'SysDash · herstart · '+t},
    '● Herstart nodig — '+m);

  // Kernel-/uitstelrisico ("risico: rood") apart van het kale aantal — één rode update is dringender dan 15 gewone
  const ul = asArr(ex.updates_list) || [];
  const nrood = ul.filter(u=>u && u.risk==='rood').length;
  fire(m,'risico',nrood>0,{title:'⚠ Kernel/uitgestelde update — '+m,subtitle:t,state:'alert',
    rows:[{label:'RISICO',value:nrood+' rood klaar',status:'high'}],footer:'SysDash · updates · '+t},
    '⚠ Kernel/uitgestelde update — '+m+' · '+nrood+' rood');
}
return out;
